      AppLanguage.marathi: 'घरातील एसी, फ्रीज, वॉशिंग मशीन, आरओ व प्लंबिंग सर्व्हिस बुक करा. दिवाळी ऑफर्स, पारदर्शक बिलिंग व ३० दिवस गॅरंटी.',
