      AppLanguage.hindi: 'घर के एसी, फ्रिज, वाशिंग मशीन, आरओ व प्लंबिंग सर्विस बुक करें। पारदर्शी बिलिंग व ३० दिन गारंटी।',
      AppLanguage.kannada: 'ಎಸಿ, ರೆಫ್ರಿಜರೇಟರ್, ಆರ್‌ಒ ಮತ್ತು ಪ್ಲಂಬಿಂಗ್ ದುರಸ್ತಿಗಳನ್ನು ೩೦ ದಿನಗಳ ಖಾತರಿಯೊಂದಿಗೆ ಬುಕ್ ಮಾಡಿ.',
      AppLanguage.gujarati: 'ઘરના એસી, ફ્રિજ, વોશિંગ મશીન, આરઓ અને પ્લમ્બિંગ સર્વિસ બુક કરો. પારદર્શક બિલિંગ અને ૩૦ દિવસ ગેરંટી.',
    },
    'नवीन कामाचे थेट अलर्ट, १-क्लिक गुगल मॅप्सने ग्राहकाचे घर शोधणे, OTP व्हेरिफिकेशन, सुटे भाग ऍड करणे व रोजची कमाई ट्रॅकिंग.': {
