  static String translate(String text, [AppLanguage? lang]) {
    final targetLang = lang ?? currentLang;
    final trimmed = text.trim();
    if (trimmed.isEmpty) return text;

    // 1. Direct dictionary match
    if (_dictionary.containsKey(trimmed)) {
      final entry = _dictionary[trimmed]!;
      if (entry.containsKey(targetLang)) {
        return entry[targetLang]!;
      }
    }

    // 2. Dynamic numeric/unit replacement (e.g. 'सक्रिय सर्व्हिसेस (12)', '30 दिवस वॉरंटी', '18 min')
    final translatedDynamic = _translateDynamicPattern(trimmed, targetLang);
    if (translatedDynamic != null) {
      return translatedDynamic;
    }

    // 3. Bilingual string like 'मराठी (English)'
    final parenMatch = RegExp(r'^(.*?)\s*\((.*?)\)$').firstMatch(trimmed);
    if (parenMatch != null) {
      final mrPart = parenMatch.group(1)?.trim() ?? trimmed;
      final enPart = parenMatch.group(2)?.trim() ?? trimmed;
      switch (targetLang) {
        case AppLanguage.marathi:
          return mrPart;
        case AppLanguage.english:
          return enPart;
        case AppLanguage.hindi:
          return trText(mrPart, enPart, AppLanguage.hindi);
        case AppLanguage.kannada:
          return trText(mrPart, enPart, AppLanguage.kannada);
        case AppLanguage.gujarati:
          return trText(mrPart, enPart, AppLanguage.gujarati);
      }
    }

    return trimmed;
  }

  static String? _translateDynamicPattern(String text, AppLanguage lang) {
    final dAgo = RegExp(r'^(\d+|\$[\w{}]+)\s*(दिवसांपूर्वी|d ago)$').firstMatch(text);
    if (dAgo != null) {
      final num = dAgo.group(1)!;
      switch (lang) {
        case AppLanguage.marathi: return '$num दिवसांपूर्वी';
        case AppLanguage.english: return '${num}d ago';
        case AppLanguage.hindi: return '$num दिन पहले';
        case AppLanguage.kannada: return '$num ದಿನಗಳ ಹಿಂದೆ';
        case AppLanguage.gujarati: return '$num દિવસ પહેલાં';
      }
    }

    final hAgo = RegExp(r'^(\d+|\$[\w{}]+)\s*(तासांपूर्वी|h ago)$').firstMatch(text);
    if (hAgo != null) {
      final num = hAgo.group(1)!;
      switch (lang) {
        case AppLanguage.marathi: return '$num तासांपूर्वी';
        case AppLanguage.english: return '${num}h ago';
        case AppLanguage.hindi: return '$num घंटे पहले';
        case AppLanguage.kannada: return '$num ಗಂಟೆಗಳ ಹಿಂದೆ';
        case AppLanguage.gujarati: return '$num કલાક પહેલાં';
      }
    }

    final mAgo = RegExp(r'^(\d+|\$[\w{}]+)\s*(मिनीटांपूर्वी|m ago)$').firstMatch(text);
    if (mAgo != null) {
      final num = mAgo.group(1)!;
      switch (lang) {
        case AppLanguage.marathi: return '$num मिनीटांपूर्वी';
        case AppLanguage.english: return '${num}m ago';
        case AppLanguage.hindi: return '$num मिनट पहले';
        case AppLanguage.kannada: return '$num ನಿಮಿಷಗಳ ಹಿಂದೆ';
        case AppLanguage.gujarati: return '$num મિનિટ પહેલાં';
      }
    }

    // Dynamic pattern: Matching Partners (${category}):
    final matchPartners = RegExp(r'^(या सेवेसाठीचे पार्टनर्स|Matching Partners)\s*\((.*)\):$').firstMatch(text);
    if (matchPartners != null) {
      final cat = matchPartners.group(2)!;
      switch (lang) {
        case AppLanguage.marathi: return 'या सेवेसाठीचे पार्टनर्स ($cat):';
        case AppLanguage.english: return 'Matching Partners ($cat):';
        case AppLanguage.hindi: return 'इस सेवा के लिए पार्टनर्स ($cat):';
        case AppLanguage.kannada: return 'ಈ ಸೇವೆಗಾಗಿ ಪಾಲುದಾರರು ($cat):';
        case AppLanguage.gujarati: return 'આ સેવા માટેના પાર્ટનર્સ ($cat):';
      }
    }

    // Dynamic pattern: Search ${cat} services...
    final matchSearchCat = RegExp(r'^(.*)\s*(सेवा शोधा\.\.\.|services\.\.\.)$').firstMatch(text);
    if (matchSearchCat != null) {
      final cat = matchSearchCat.group(1)!.replaceAll(RegExp(r'Search\s*'), '').trim();
      switch (lang) {
        case AppLanguage.marathi: return '$cat सेवा शोधा...';
        case AppLanguage.english: return 'Search $cat services...';
        case AppLanguage.hindi: return '$cat सेवाएं खोजें...';
        case AppLanguage.kannada: return '$cat ಸೇವೆಗಳನ್ನು ಹುಡುಕಿ...';
        case AppLanguage.gujarati: return '$cat સેવાઓ શોધો...';
      }
    }

    // Dynamic count patterns like "सक्रिय सर्व्हिसेस (5)", "Active Services (5)", "सर्व (10)", etc.
    final countMatch = RegExp(r'^(.*?)\s*\((\d+|\$[\w{}]+)\)$').firstMatch(text);
    if (countMatch != null) {
      final prefix = countMatch.group(1)!.trim();
      final count = countMatch.group(2)!;
      final transPrefix = translate(prefix, lang);
      if (transPrefix != prefix) {
        return '$transPrefix ($count)';
      }
    }

    // Dynamic name patterns like "नवीन पार्टनर (Ramesh) जोडला!"
    final partnerAdded = RegExp(r'^(नवीन पार्टनर|Partner)\s*\((.*?)\)\s*(जोडला!|registered!)$').firstMatch(text);
    if (partnerAdded != null) {
      final name = partnerAdded.group(2)!;
      switch (lang) {
        case AppLanguage.marathi: return 'नवीन पार्टनर ($name) जोडला!';
        case AppLanguage.english: return 'Partner ($name) registered!';
        case AppLanguage.hindi: return 'नया पार्टनर ($name) जोड़ा गया!';
        case AppLanguage.kannada: return 'ಹೊಸ ಪಾಲುದಾರ ($name) ನೋಂದಾಯಿಸಲಾಗಿದೆ!';
        case AppLanguage.gujarati: return 'નવો પાર્ટનર ($name) ઉમેરાયો!';
      }
    }

    // Greeting: "नमस्कार, Ramesh! 👋" / "Hello, Ramesh! 👋"
    final helloUser = RegExp(r'^(नमस्कार,|Hello,)\s*(.*?)(! 👋)$').firstMatch(text);
    if (helloUser != null) {
      final user = helloUser.group(2)!.trim();
      switch (lang) {
        case AppLanguage.marathi: return 'नमस्कार, $user! 👋';
        case AppLanguage.english: return 'Hello, $user! 👋';
        case AppLanguage.hindi: return 'नमस्ते, $user! 👋';
        case AppLanguage.kannada: return 'ನಮಸ್ಕಾರ, $user! 👋';
        case AppLanguage.gujarati: return 'નમસ્તે, $user! 👋';
      }
    }

    // Technician on the way: "$serviceName साठी तंत्रज्ञ येत आहेत"
    final techOnWay = RegExp(r'^(.*?)\s*(साठी तंत्रज्ञ येत आहेत|Technician on the way for (.*))$').firstMatch(text);
    if (techOnWay != null) {
      final sName = (techOnWay.group(3) ?? techOnWay.group(1))!.trim();
      switch (lang) {
        case AppLanguage.marathi: return '$sName साठी तंत्रज्ञ येत आहेत';
        case AppLanguage.english: return 'Technician on the way for $sName';
        case AppLanguage.hindi: return '$sName के लिए तकनीशियन आ रहे हैं';
        case AppLanguage.kannada: return '$sName ಗಾಗಿ ತಂತ್ರಜ್ಞರು ಬರುತ್ತಿದ್ದಾರೆ';
        case AppLanguage.gujarati: return '$sName માટે ટેકનિશિયન આવી રહ્યા છે';
      }
    }

    // Price per unit: "₹100 प्रति युनिट" / "₹100 per unit with warranty"
    final priceUnit = RegExp(r'^(₹[\d,.]+|\$[\w{}]+)\s*(प्रति युनिट|per unit with warranty)$').firstMatch(text);
    if (priceUnit != null) {
      final price = priceUnit.group(1)!;
      switch (lang) {
        case AppLanguage.marathi: return '$price प्रति युनिट';
        case AppLanguage.english: return '$price per unit with warranty';
        case AppLanguage.hindi: return '$price प्रति यूनिट वारंटी के साथ';
        case AppLanguage.kannada: return '$price ಪ್ರತಿ ಯುನಿಟ್‌ಗೆ ವಾರಂಟಿಯೊಂದಿಗೆ';
        case AppLanguage.gujarati: return '$price પ્રતિ યુનિટ વોરંટી સાથે';
      }
    }

    return null;
  }

  static String trText(
    String mr,
    String en,
    AppLanguage lang, {
    String? hi,
    String? kn,
    String? gu,
  }) {
    switch (lang) {
      case AppLanguage.marathi:
        return mr;
      case AppLanguage.english:
        return en;
      case AppLanguage.hindi:
        return hi ?? _dictionary[mr]?[AppLanguage.hindi] ?? _dictionary[en]?[AppLanguage.hindi] ?? translate(mr, AppLanguage.hindi);
      case AppLanguage.kannada:
        return kn ?? _dictionary[en]?[AppLanguage.kannada] ?? _dictionary[mr]?[AppLanguage.kannada] ?? translate(en, AppLanguage.kannada);
      case AppLanguage.gujarati:
        return gu ?? _dictionary[mr]?[AppLanguage.gujarati] ?? _dictionary[en]?[AppLanguage.gujarati] ?? translate(mr, AppLanguage.gujarati);
    }
  }

  static String tr(
    dynamic mr,
    dynamic en, {
    String? hi,
    String? kn,
    String? gu,
  }) {
    final mrStr = mr?.toString() ?? '';
    final enStr = en?.toString() ?? '';
    return trText(mrStr, enStr, currentLang, hi: hi, kn: kn, gu: gu);
  }

  static List<String> trList(List<String> mr, List<String> en) {
    switch (currentLang) {
      case AppLanguage.marathi: return mr;
      case AppLanguage.english: return en;
      case AppLanguage.hindi:
        return mr.map((item) => translate(item, AppLanguage.hindi)).toList();
      case AppLanguage.kannada:
        return en.map((item) => translate(item, AppLanguage.kannada)).toList();
      case AppLanguage.gujarati:
        return mr.map((item) => translate(item, AppLanguage.gujarati)).toList();
    }
  }
}

String tr(dynamic mr, dynamic en, {String? hi, String? kn, String? gu}) =>
    AppTranslations.tr(mr, en, hi: hi, kn: kn, gu: gu);

List<String> trList(List<String> mr, List<String> en) =>
    AppTranslations.trList(mr, en);

extension AppTranslationExtension on String {
  String tr([AppLanguage? lang]) => AppTranslations.translate(this, lang);
}
